void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
void click(CanvasView& view,double x,double y,double time,bool control=false){using K=ii::gui::WidgetInputKind;ii::gui::WidgetInput e;e.x=x;e.y=y;e.buttons=1;e.timestamp=time;e.control=control;e.kind=K::pointer_down;check(view.input(e).has_value(),"magnetic down failed");e.kind=K::pointer_up;check(view.input(e).has_value(),"magnetic up failed");}
void key(CanvasView& view,ii::gui::WidgetKey k){ii::gui::WidgetInput e;e.kind=ii::gui::WidgetInputKind::key_down;e.key=k;check(view.input(e).has_value(),"magnetic key failed");}
